#!/bin/bash
# experiments_full.sh [--old-generated-code] -- full experiments: every family, size, instance and library of the paper's body (Fig. 2 and 3; Tables 5, 7-9, 11-24, 26-28),
# with code exports generated by an Isabelle build of the library.
# Setup (setup/setup.sh full) and then the measurements (run/run.sh full); both can also be run on their own.
# --old-generated-code measures the code exports the paper's numbers were made with (exports/campaign) instead.
# Takes about 18 days (see README.md).  Results: evaluation/results/<date>_full/.
set -uo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
bash "$here/setup/setup.sh" full "$@" || { echo "setup failed, see evaluation/work/setup_full.log" >&2; exit 1; }
exec bash "$here/run/run.sh" full "$@"
